  "implementation": "def solve(case):
    # Extract inputs
    nodes = case.get('nodes')
    required_symbols = case.get('required_symbols')
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError('Invalid case structure')

    # Build lookup and children mapping
    node_by_id = {}
    children_of = {}
    for n in nodes:
        nid = n.get('id')
        if not isinstance(nid, str):
            raise ValueError('Node missing id')
        node_by_id[nid] = n
        children_of[nid] = []
    for n in nodes:
        parent = n.get('parent')
        if parent is not None:
            if parent not in children_of:
                raise ValueError(f'Parent {parent} not found')
            children_of[parent].append(n['id'])

    required_set = set(required_symbols)

    # Candidate order: deeper first, then by ID ascending
    candidate_ids = sorted(node_by_id.keys(), key=lambda x: (-node_by_id[x]['depth'], x))

    removed_set = set()
    removed_order = []

    for cid in candidate_ids:
        if cid in removed_set:
            continue
        node = node_by_id[cid]
        if not node.get('removable', False):
            continue
        # Check retained children
        has_retained_child = False
        for child in children_of.get(cid, []):
            if child not in removed_set:
                has_retained_child = True
                break
        if has_retained_child:
            continue
        # Collect subtree nodes (excluding already removed)
        subtree = []
        stack = [cid]
        while stack:
            nid = stack.pop()
            if nid in removed_set:
                continue
            subtree.append(nid)
            for child in children_of.get(nid, []):
                stack.append(child)
        # Compute required symbols in subtree
        subtree_req = set()
        for nid in subtree:
            sym = node_by_id[nid]['symbol']
            if sym in required_set:
                subtree_req.add(sym)
        # Compute global required symbol counts among remaining nodes (excluding subtree)
        global_counts = {}
        for n in nodes:
            nid = n['id']
            if nid in removed_set or nid in subtree:
                continue
            sym = n['symbol']
            if sym in required_set:
                global_counts[sym] = global_counts.get(sym, 0) + 1
        # Also add counts from nodes in subtree that will be removed (they are not counted in global)
        # Check each required symbol in subtree: is there at least one outside?
        can_remove = True
        for sym in subtree_req:
            count_in_subtree = sum(1 for nid in subtree if node_by_id[nid]['symbol'] == sym)
            # Global count already excludes subtree and removed
            if global_counts.get(sym, 0) == 0 and count_in_subtree > 0:
                # No other occurrence outside subtree
                can_remove = False
                break
        if not can_remove:
            continue
        # Remove the entire subtree
        removed_set.update(subtree)
        removed_order.append(cid)

    retained_ids = sorted([n['id'] for n in nodes if n['id'] not in removed_set])
    return {
        'removed_node_ids': removed_order,
        'retained_node_ids': retained_ids
    }"
}
